import{_ as n,a0 as o,w as r,s,ao as d,I as a,a1 as e,A as p,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Picty:讓圖片管理變簡單 | LCTT x X-CMD","titleTemplate":false,"description":"Picty:讓圖片管理變簡單 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Picty:讓圖片管理變簡單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Picty:讓圖片管理變簡單 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150330 Picty--Managing Photos Made Easy","title":"Picty:讓圖片管理變簡單","tag":"201504","desc":""},"relativePath":"201504/20150330 Picty--Managing Photos Made Easy.md","filePath":"[post].md"}'),u={name:"201504/20150330 Picty--Managing Photos Made Easy.md"};function y(c,t,m,g,P,h){const l=o("Link");return r(),s("div",null,[t[14]||(t[14]=d(`<h1 id="picty-讓圖片管理變簡單" tabindex="-1">Picty:讓圖片管理變簡單 <a class="header-anchor" href="#picty-讓圖片管理變簡單" aria-label="Permalink to “Picty:讓圖片管理變簡單”">​</a></h1><p><img src="http://1102047360.rsc.cdn77.org/wp-content/uploads/2015/03/picty_002-790x429.png" alt=""></p><h3 id="關於picty" tabindex="-1">關於Picty <a class="header-anchor" href="#關於picty" aria-label="Permalink to “關於Picty”">​</a></h3><p><strong>Picty</strong>是個免費，簡單，卻強大的照片收藏管理器，它可以幫助你管理你的照片。它是圍繞着<strong>元數據</strong>管理和圖像<strong>無損</strong>處理設計的。Picty目前同時支持在線（基於網頁的）和離線（本地的）收藏集。在本地的收藏集中，圖片將被保存在一個本地的文件夾及其子文件夾中。為了加快用户主目錄裏圖片的查詢速度，它會維持一個數據庫。在在線（基於網頁的）收藏集中，你可以通過網頁瀏覽器上傳並分享圖片。擁有適當權限的個人用户可以把圖片分享給任何人，而且用户可以同時打開多個收藏集，收藏集也可以分享給多個用户。有個簡單的界面可以通過傳輸插件在收藏集之間傳輸圖片。</p><p>你可以從你的相機或任何設備中下載任何數量的照片。除此之外，Picty允許你在下載前瀏覽在你相機裏的圖片集。Picty是個輕量級的應用，界面清爽。它支持Linux和Windows平台。</p><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><ul><li>支持大相片集（20000張以上）。</li><li>同時打開多個收藏集，還可以在它們之間傳照片。</li><li>收藏集包括： <ul><li>本地文件系統中保存圖片的文件夾。</li><li>相機、電話及其他媒體設備中的圖片。</li><li>圖片保存服務（目前支持Flickr）</li></ul></li><li>Picty不是把相片“導入”到它的資料庫中，它僅僅提供了一個界面來訪問它們，不管它們保存在哪。為了保持迅速的反應以及能使你在離線時瀏覽圖片的能力，Picty會保存縮略圖和元數據的緩存。</li><li>以業界標準格式Exif、IPTC和Xmp讀寫元數據。</li><li>無損的方法： <ul><li>Picty把所有改變包括圖像編輯以元數據的方式寫入。例如，一個圖片可以以任何方式剪切保存，原來的圖像仍然保存在該文件裏。</li><li>修改會保存在Picty的收藏集緩存中直到你把你對元數據的修改保存到圖片中，所以你能很容易撤銷你不喜歡的未保存的修改。</li></ul></li><li>基本圖片編輯功能： <ul><li>目前支持基本的圖像增強，如亮度、對比度、色彩、剪切以及矯正。</li><li>將要推出一些工具改進及更多工具。（紅眼消除、拉伸、彎曲、噪聲消除）</li></ul></li><li>圖片標籤： <ul><li>使用標準的IPTC和Xmp關鍵詞為圖片做標籤。</li><li>一個樹狀標籤圖讓你能很容易的管理標籤和在收藏集內導航。</li></ul></li><li>文件夾視圖： <ul><li>按照目錄的結構對你的圖片收藏集進行導航</li></ul></li><li>支持多屏顯示 <ul><li>Picty可以設置成讓你在一個屏幕上瀏覽你的收藏集同時在另一個屏幕上全屏顯示圖片。</li></ul></li><li>可個性化 <ul><li>可以為外部工具創建快捷方式</li><li>支持插件——目前提供的功能中有許多（標籤和文件夾視圖以及所有的圖片編輯工具）都可以通過插件提供。</li><li>使用Python編寫——內置電池(batteries included)！</li></ul></li></ul><h3 id="安裝方法" tabindex="-1">安裝方法 <a class="header-anchor" href="#安裝方法" aria-label="Permalink to “安裝方法”">​</a></h3><h4 id="_1、從ppa安裝" tabindex="-1">1、從PPA安裝 <a class="header-anchor" href="#_1、從ppa安裝" aria-label="Permalink to “1、從PPA安裝”">​</a></h4><p>Picty開發人員為Ubuntu這樣的基於 Debian的發行版創建了一個PPA，讓安裝更簡單。</p><p>要在Ubuntu和它的衍生版上安裝，請運行以下命令：</p><pre><code>sudo add-apt-repository ppa:damien-moore/ppa
sudo apt-get update
sudo apt-get install picty
</code></pre><h4 id="_2、從源文件安裝" tabindex="-1">2、從源文件安裝 <a class="header-anchor" href="#_2、從源文件安裝" aria-label="Permalink to “2、從源文件安裝”">​</a></h4><p>此外，你還可以從源文件安裝。首先安裝如下依賴項。</p><pre><code>sudo apt-get install bzr python-pyinotify python-pyexiv2 python-gtk2 python-gnome2 dcraw python-osmgpsmap python-flickrapi
</code></pre><p>然後，使用下面這個命令得到最新版本：</p><pre><code>bzr branch lp:picty
</code></pre><p>要運行Picty，先轉到Picty所在的目錄，然後輸入：</p><pre><code>cd picty
bin/picty
</code></pre><p>要想更新到最新版，請運行：</p><pre><code>cd picty
bzr pull
</code></pre><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h3><p>可以從目錄或Unity Dash啓動Picty。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/picty_001.png" alt="picty_001"></p><p>你可以選擇已存在的收藏集、設備或目錄。這裏讓我們創建一個<strong>新收藏集</strong> ，請先點擊新收藏集（New Collection）按鈕。進入收藏集，然後瀏覽到你保存圖片的地方。最後，點擊<strong>創建（Create）</strong>按鈕。</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/Create-a-Collection_001.png" alt="Create a Collection_001"></p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/03/picty_002.png" alt="picty_002"></p><p>你可以對每張圖片進行修改，旋轉，添加/移除標籤，設置描述。只需右擊任何一個圖片然後愛做什麼做什麼。</p><p>訪問下面這個Google組可以得到更多關於Picty相片管理器的信息和支持。</p>`,29)),a("ul",null,[a("li",null,[e(l,{href:"http://groups.google.com/group/pictyphotomanager"},{default:p(()=>[...t[0]||(t[0]=[i("http://groups.google.com/group/pictyphotomanager",-1)])]),_:1})])]),t[15]||(t[15]=a("p",null,"乾杯！",-1)),t[16]||(t[16]=a("hr",null,null,-1)),a("p",null,[t[2]||(t[2]=i("via: ",-1)),e(l,{href:"http://www.unixmen.com/picty-managing-photos-made-easy/"},{default:p(()=>[...t[1]||(t[1]=[i("http://www.unixmen.com/picty-managing-photos-made-easy/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=i("作者：",-1)),e(l,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...t[3]||(t[3]=[i("SK",-1)])]),_:1}),t[7]||(t[7]=i(" 譯者：",-1)),e(l,{href:"https://github.com/H-mudcup"},{default:p(()=>[...t[4]||(t[4]=[i("H-mudcup",-1)])]),_:1}),t[8]||(t[8]=i(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=i("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[9]||(t[9]=[i("LCTT",-1)])]),_:1}),t[12]||(t[12]=i(" 原創翻譯，",-1)),e(l,{href:"http://linux.cn/"},{default:p(()=>[...t[10]||(t[10]=[i("Linux中國",-1)])]),_:1}),t[13]||(t[13]=i(" 榮譽推出",-1))])])}const b=n(u,[["render",y]]);export{w as __pageData,b as default};
